"""Whole lib/sort.c: byte-offset heapsort and public callback contracts."""
def register(topic, q, detail):
    def lesson(title, symbol, why, principle, use, reading, qa, cards):
        topic(title, '라이브러리·알고리즘', 'lib/sort.c', symbol,
              why, principle, use, reading, *(q(*x) for x in qa),
              details=[detail(*x) for x in cards])

    lesson('배열 정렬·교환 폭과 정렬된 주소', 'is_aligned',
        '배열을 정렬할 때 원소를 안전하고 빠르게 교환할 수 있는 폭을 고르는 이유를 배웁니다.',
        '원소 크기가 8의 배수이면 다음 원소도 같은 8바이트 경계에 놓입니다. 효율적인 비정렬 접근을 지원하지 않는 설정에서는 시작 주소도 그 경계에 있어야 합니다. 주소와 크기의 낮은 비트를 OR한 뒤 align-1로 검사하면 두 조건을 함께 확인합니다. CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS 설정에서는 시작 주소 조건을 생략합니다.',
        'align은 여기에서 4 또는 8입니다. 임의의 정수 정렬 단위를 넣는 일반 나머지 검사로 쓰지 않습니다. 배열의 실제 원소 크기와 시작 주소를 함께 확인하고 설정에 맞는 교환 경로를 선택합니다.',
        'unsigned char 변환, 설정 분기, align-1 마스크를 읽으세요.',
        [('비정렬 접근을 허용하지 않는 설정에서 크기 8, 시작 주소의 나머지 4라면?', '8바이트 교환 조건을 만족하지 않는다', '크기만 8이면 항상 만족한다', '원소 간 간격은 맞지만 첫 주소가 8의 배수가 아닙니다. 이 설정은 주소와 크기를 함께 검사합니다.'),
         ('주소와 크기를 OR한 뒤 낮은 비트를 검사하는 이유는?', '둘 중 하나라도 해당 비트가 있으면 조건을 거절하기 위해서다', '두 숫자의 평균을 구하기 위해서다', 'OR는 어느 입력에든 있는 비트를 남깁니다. 두 입력 모두 정렬 경계의 낮은 비트가 0이어야 통과합니다.')],
        [('C 속성', '__attribute_const__와 __always_inline은 컴파일러를 위한 속성입니다. 자료를 교환하거나 메모리를 할당하는 동작이 이 검사에 추가되는 것은 아닙니다.'),
         ('크기 조건', '검사는 2의 거듭제곱 정렬 단위를 전제로 합니다. 뒤의 교환 함수는 양수이며 해당 폭의 배수인 크기를 요구합니다.')])

    lesson('배열 교환·32비트 조각을 뒤에서 복사하기', 'swap_words_32',
        '일반 구조체 전체를 고정된 크기의 조각으로 교환하는 반복문의 동작을 배웁니다.',
        'n에서 4를 먼저 뺀 위치의 u32를 임시 변수에 저장합니다. 같은 위치의 b를 a에 복사한 뒤 임시 값을 b에 넣습니다. n이 0이 될 때까지 뒤쪽 조각에서 앞쪽 조각으로 진행합니다. 한 조각의 값을 먼저 보관해야 첫 번째 대입으로 덮어쓴 자료를 복원할 수 있습니다.',
        '호출자는 양수이며 4의 배수인 원소 크기와 설정에 맞는 접근 가능한 주소를 제공해야 합니다. 이 함수는 크기 0이나 임의의 바이트 수를 자체 검사하지 않습니다. 일반 응용 C에서는 정렬과 alias 규칙을 따르는 복사 방식을 따로 선택합니다.',
        'n -= 4가 접근 전에 실행되는 순서와 세 대입을 읽으세요.',
        [('크기 12의 교환에서 처음 접근하는 바이트 위치는?', '8이다', '12이다', '먼저 n을 4 줄이므로 마지막 4바이트 조각은 위치 8부터 시작합니다. 위치 12는 원소 바로 뒤입니다.'),
         ('첫 값을 임시 변수에 저장하지 않으면 무엇이 사라지는가?', 'a의 원래 조각 값이다', '원소 크기를 계산하는 설정 파일이다', 'a에 b를 먼저 대입하면 a의 이전 값이 덮어써집니다. 임시 변수는 그 값을 b에 넣기 위해 필요합니다.')],
        [('GNU C 포인터 산술', '원본의 void 포인터 더하기는 GNU C 확장입니다. 표준 C에서 바이트 단위 이동을 표현하려면 문자 포인터 등을 사용합니다.'),
         ('사용 범위', '정렬 배열의 서로 다른 원소를 교환하는 경로입니다. 임의로 겹치는 메모리 영역에 대한 memmove 계약을 제공하지 않습니다.')])

    lesson('배열 교환·64비트 설정과 두 번의 32비트 전송', 'swap_words_64',
        '같은 8바이트 교환이 커널 설정에 따라 다른 명령 폭으로 구현되는 이유를 배웁니다.',
        'CONFIG_64BIT 분기는 n을 8 줄인 뒤 u64 한 개를 교환합니다. 다른 분기는 n을 4씩 두 번 줄여 u32 두 개를 교환합니다. 두 방식 모두 한 반복에서 8바이트를 처리합니다. 주석은 64비트 전송을 흉내 낼 때 주소 계산 비용이 커질 수 있어 두 32비트 전송을 선택한 이유를 설명합니다.',
        '크기는 양수이며 8의 배수여야 합니다. 설정 분기의 산술과 자료 보존을 비교할 수 있지만 64비트 호스트에서 설정만 바꾼 시험을 실제 32비트 ABI나 해당 CPU의 성능 측정으로 표현하지 않습니다.',
        'CONFIG_64BIT의 양쪽에서 n이 총 8 줄어드는지 확인하세요.',
        [('64비트 설정이 꺼진 한 반복에서 n은 얼마나 줄어드는가?', '두 번의 4바이트 처리로 총 8 줄어든다', '한 번의 4바이트 처리로 총 4만 줄어든다', '두 교환 구문이 각각 n -= 4를 실행합니다. 전체 반복의 처리 폭은 여전히 8바이트입니다.'),
         ('두 설정 경로가 보존해야 하는 결과는?', '두 원소의 모든 바이트가 서로 바뀐 결과다', '설정에 따라 원소의 절반을 삭제한 결과다', '선택되는 전송 폭은 달라도 교환의 의미는 같습니다. 크기의 모든 조각을 교환해야 합니다.')],
        [('바이트 순서', '수치 값을 해석해 다시 직렬화하지 않고 같은 폭의 값을 읽고 씁니다. 교환 자체는 두 원소의 저장 내용을 서로 옮기는 동작입니다.'),
         ('성능 판단', '소스 주석의 주소 계산 설명과 실제 대상 CPU의 실행 시간을 구분합니다. 분기 선택만으로 모든 CPU에서의 속도 우열을 증명할 수 없습니다.')])

    lesson('배열 교환·바이트 단위 대체 경로', 'swap_bytes',
        '원소 크기나 주소가 넓은 전송 조건을 만족하지 않을 때 쓰는 대체 동작을 배웁니다.',
        'n을 하나 줄인 바이트 위치에서 a와 b를 char 임시 변수로 교환합니다. 매번 한 바이트를 처리하므로 원소 크기가 4 또는 8의 배수일 필요가 없습니다. do-while이 첫 교환을 무조건 실행하므로 내부 함수에는 양수 크기 조건이 여전히 필요합니다.',
        'sort_r는 원소 크기가 0이면 이 함수에 도달하기 전에 반환합니다. 작은 홀수 크기 구조와 주소 조건을 가진 배열의 교환을 관찰하되 배열 경계 밖 자료를 바꾸지 않는지 함께 확인합니다.',
        '--n과 char 포인터의 배열 접근을 읽으세요.',
        [('크기 3의 바이트 교환 순서는?', '위치 2, 1, 0이다', '위치 3, 2, 1이다', '매번 감소를 먼저 실행합니다. 마지막 바이트부터 첫 바이트까지 정확히 세 위치를 처리합니다.'),
         ('내부 swap_bytes에 직접 크기 0을 주어도 안전한가?', '안전하지 않으며 호출 전 조건이 필요하다', 'do-while은 반드시 아무 작업 없이 끝난다', 'do-while 본문이 먼저 실행되어 --n이 발생합니다. 공개 정렬 함수의 조기 반환과 내부 함수의 계약을 구분해야 합니다.')],
        [('구조체 패딩', '기본 교환은 논리 필드만 골라 옮기지 않고 원소 저장 공간 전체를 교환합니다. 비교 함수는 실제 비교할 필드를 선택해야 합니다.'),
         ('외부 참조', '원소를 가리키는 별도 위치 정보가 있다면 단순 저장 내용 교환만으로 그 정보를 유지하지 못할 수 있습니다. 맞춤 교환 함수가 필요한지 검토합니다.')])

    lesson('정렬 콜백·내장 교환 선택값과 priv 전달', 'do_swap',
        '함수 포인터처럼 보이는 값 중 일부가 내부 선택 표식으로 사용되는 구조를 배웁니다.',
        'SWAP_WORDS_64, SWAP_WORDS_32, SWAP_BYTES, SWAP_WRAPPER는 작은 정수를 함수 포인터 형식으로 변환한 내부 선택값입니다. do_swap은 먼저 표식을 비교해 실제 내부 함수를 호출합니다. 일반 콜백이면 마지막 인자로 priv를 전달합니다. WRAPPER이면 struct wrapper에 저장한 기존 형식의 콜백을 호출합니다. do_cmp도 비교 표식에 따라 기존 형식 또는 priv 형식을 선택합니다.',
        '공개 호출에는 정상적인 콜백 또는 NULL을 제공합니다. 내부 표식을 응용 코드의 호출 가능한 함수 주소로 취급하지 않습니다. 맞춤 교환 함수의 크기 인자는 int이므로 원소 크기의 표현 가능 범위도 호출자가 지켜야 합니다.',
        '표식 비교가 간접 함수 호출보다 먼저 실행되는 순서를 읽으세요.',
        [('SWAP_BYTES 표식을 함수 주소라고 생각하고 직접 호출하면 되는가?', '안 되며 do_swap의 선택 분기를 거쳐야 한다', '작은 정수 2는 항상 유효한 함수 주소다', '표식은 내부 분류 값입니다. 원본은 이를 비교해서 swap_bytes를 호출하며 표식 자체를 함수로 실행하지 않습니다.'),
         ('sort_r의 일반 비교 콜백에 priv가 전달되는 이유는?', '비교에 필요한 외부 문맥을 명시적으로 제공하기 위해서다', '원소를 반드시 전역 변수로 옮기기 위해서다', 'do_cmp는 a, b와 priv를 함께 전달합니다. 호출자는 문맥 객체를 통해 비교 기준을 선택할 수 있습니다.')],
        [('Retpoline', '원본은 내장 교환을 직접 선택하면 간접 호출의 retpoline 비용을 피할 수 있다고 설명합니다. retpoline은 추측 실행을 제한하는 간접 분기 기법이며 이 함수가 그 기법 전체를 구현하는 것은 아닙니다.'),
         ('비교 계약', '비교 함수는 앞 원소가 작으면 음수, 같으면 0, 크면 양수를 반환하도록 일관된 순서를 제공해야 합니다. 단순 정수 뺄셈은 부호 있는 overflow를 일으킬 수 있으므로 대소 비교를 이용합니다.')])

    lesson('힙 부모 계산·바이트 위치에서 나눗셈 줄이기', 'parent',
        '배열 인덱스 대신 바이트 위치를 사용할 때 부모 위치를 정확히 구하는 기법을 배웁니다.',
        '원소 인덱스 j의 부모는 (j-1)/2의 정수 몫입니다. 바이트 위치 i=j*size를 먼저 size만큼 줄입니다. 그 결과의 lsbit가 켜져 있으면 size를 한 번 더 빼서 짝수 원소 배수로 만듭니다. 마지막으로 2로 나누면 부모의 바이트 위치가 됩니다. lsbit=size & -size는 크기에서 가장 낮은 1비트입니다.',
        'i는 0이 아닌 유효한 원소 위치이며 size는 양수입니다. size & -(i & lsbit)의 선택 마스크는 부호 없는 나머지 산술에 의존합니다. 이 함수를 임의의 바이트 주소를 부모 주소로 바꾸는 범용 함수로 사용하지 않습니다.',
        'size 12에서 자식 인덱스 1, 2, 3, 4를 직접 계산하세요.',
        [('크기 12, 자식 바이트 위치 48의 부모 위치는?', '12이다', '24이다', '자식 인덱스는 4이고 부모 인덱스는 (4-1)/2=1입니다. 48에서 12를 빼면 36, 낮은 1비트 조건으로 12를 더 빼고 2로 나누면 12입니다.'),
         ('바이트 위치에서 단순히 (i-size)/2를 사용하면 어떤 문제가 있는가?', '홀수 원소 배수의 절반이 원소 중간을 가리킬 수 있다', '모든 부모가 자동으로 배열 끝으로 이동한다', '크기 12에서 i=48이면 단순 식은 18입니다. 유효한 부모 위치 12와 다르므로 원소 배수를 보정해야 합니다.')],
        [('마스크의 선택', 'i & lsbit가 0이면 빼는 추가 값도 0입니다. 해당 비트가 켜지면 size의 가장 낮은 1비트 성질을 이용해 추가 size를 선택합니다.'),
         ('표현 범위', '원본 lsbit 변수는 unsigned int입니다. 실제 커널 원소 크기 범위와 전체 배열의 num*size 표현 가능 조건을 지키며 임의의 거대한 크기에 대한 범용 보장을 추가하지 않습니다.')])

    lesson('커널 배열 정렬·바닥까지 내려갔다 되짚는 힙 구성', 'sort_r',
        '추가 배열과 재귀 없이 최대 힙을 만들고 비교 횟수를 줄이는 정렬 원리를 배웁니다.',
        'a=(num/2)*size에서 마지막 부모부터 시작합니다. 각 위치에서 더 큰 자식을 선택하며 잎까지 경로를 찾습니다. 목표 원소와 경로의 값을 비교하면서 부모 방향으로 되짚어 들어갈 위치를 찾습니다. 이어 경로의 조상과 목적지를 교환해 원소를 배치합니다. 힙 구성 중 [a,n)은 부모가 자식보다 작지 않은 조건을 만족합니다.',
        '배열과 원소 크기, 일관된 비교 함수를 제공하고 배열 변경 중 다른 접근을 보호합니다. 정렬은 입력 배열을 직접 바꾸며 같은 키의 기존 순서를 보존하는 안정 정렬을 보장하지 않습니다. 크기 0 또는 원소 수 0·1은 조기에 반환합니다.',
        'a, b, c, d를 원소 인덱스로도 적어 보고 마지막 외톨이 자식 분기를 추적하세요.',
        [('바닥까지 경로를 먼저 찾는 방식의 목적은?', '일반적인 하강에서 각 층마다 두 번 비교하는 비용을 줄이기 위해서다', '모든 원소를 별도 배열에 복사하기 위해서다', '먼저 큰 자식을 선택하는 한 비교로 층을 내려가고 이후 삽입 위치를 되짚습니다. 목표 원소가 잎 가까이 내려가는 경우 비교를 줄입니다.'),
         ('이 heapsort가 같은 키의 입력 순서를 보존한다고 볼 수 있는가?', '보장할 수 없다', '힙이므로 반드시 안정 정렬이다', '먼 위치 원소를 교환하는 힙 정렬입니다. 비교가 같은 두 원소의 원래 순서가 결과에서도 유지된다는 계약이 없습니다.')],
        [('마지막 자식', 'd==n이면 왼쪽 자식 c만 있고 오른쪽 형제가 없습니다. 그 경우 c를 경로 끝으로 선택하여 범위 밖 d를 비교하지 않습니다.'),
         ('시간과 공간', '원본은 평균과 최악 O(n log n)을 설명합니다. 재귀 호출이나 크기 n의 보조 배열을 만들지 않습니다. 비교·교환 콜백 자체의 비용은 전체 실행 비용에 별도로 영향을 줍니다.')])

    lesson('힙 정렬·두 최댓값 추출과 마지막 작은 배열', 'sort_r',
        '최대 힙에서 배열 뒤쪽을 확정하고 작은 나머지를 마무리하는 제어 흐름을 배웁니다.',
        '힙 구성이 끝나 a가 0이면 루트 최댓값을 n-size 위치로 교환합니다. 두 자식을 비교해 더 큰 자식을 고르며 그 값은 두 번째 최댓값이므로 다음 끝 위치로 교환합니다. 줄어든 힙을 복구하고 [n,num*size)의 정렬된 꼬리를 늘립니다. 마지막 2·3개는 별도 마무리 교환과 비교로 정렬합니다.',
        '추출 중 n은 전체 배열 길이가 아닌 남은 힙의 바이트 길이입니다. shift는 선택한 자식과 후속 복구 위치를 조정합니다. 0·1개 조기 반환과 2·3개 마무리, 중복 키, 내림차순 비교 기준을 각각 관찰합니다.',
        'n > 3*size 분기와 루프 뒤 n -= size를 구분해 읽으세요.',
        [('최대 힙에서 루트를 제거한 직후 두 번째 최댓값은 어디에서 찾는가?', '루트의 두 자식 중 더 큰 값에서 찾는다', '항상 가장 깊은 잎에서 찾는다', '각 자식은 자기 아래 원소보다 작지 않습니다. 루트를 제외한 나머지의 최댓값은 두 자식 중 하나에 있습니다.'),
         ('정렬 중 [n,num*size) 구간은 무엇인가?', '이미 뒤쪽 순서가 확정된 구간이다', '앞으로 다시 무조건 무작위로 섞을 구간이다', '최댓값을 뒤로 옮기고 n을 줄이므로 확정된 꼬리가 늘어납니다. 남은 힙 복구는 n 이전 구간에서 진행합니다.')],
        [('두 번째 복구', '첫 추출에서 루트에 옮긴 작은 값과 두 번째 추출에서 선택 자식에 옮긴 값을 모두 처리해야 합니다. shift와 a의 감소 흐름을 함께 추적해야 한 번의 복구로 오해하지 않습니다.'),
         ('경계와 overflow', '원본은 num*size, 자식 위치 2*b+size 등의 overflow를 공개 함수에서 검사하지 않습니다. 실제 접근 가능한 배열과 표현 가능한 계산 범위는 호출자 조건입니다.')])

    lesson('sort·기존 콜백을 sort_r로 연결하는 래퍼', 'sort',
        '문맥 인자가 없는 API와 있는 API가 같은 정렬 구현을 공유하는 방법을 배웁니다.',
        'sort는 비교·교환 함수 포인터를 지역 struct wrapper에 저장하고 sort_r에 그 주소를 priv로 전달합니다. _CMP_WRAPPER와 SWAP_WRAPPER 표식은 do_cmp와 do_swap에 기존 형식 콜백을 선택하게 합니다. 교환 함수가 NULL이면 sort_r는 표식을 기본 교환 선택 경로로 바꿉니다. sort_r가 반환하기 전까지만 지역 wrapper를 사용하므로 주소를 장기 보관하지 않습니다.',
        '간단한 비교 기준에는 sort를, 외부 문맥이 필요한 기준에는 sort_r를 사용합니다. include/linux/sort.h는 두 함수 선언을 제공하고 linux/types.h의 콜백 형식에 연결됩니다. EXPORT_SYMBOL은 다른 커널 코드·모듈이 심볼을 사용할 수 있게 하는 표시이며 사용자 프로그램의 libc API와 구분합니다.',
        '지역 wrapper 초기화, 표식 인자, NULL 교환 처리와 두 공개 선언을 연결하세요.',
        [('sort에 NULL 교환 함수를 주면 어떻게 되는가?', 'sort_r가 기본 교환 경로를 선택한다', 'WRAPPER 표식을 NULL 함수로 무조건 호출한다', 'sort_r는 wrapper의 swap이 없는지 먼저 확인합니다. 없으면 NULL로 바꾸고 주소와 크기에 맞는 내장 교환을 선택합니다.'),
         ('sort의 지역 wrapper 주소는 왜 호출 중 사용할 수 있는가?', 'sort_r가 같은 호출 안에서 사용하고 반환하기 때문이다', '지역 변수가 항상 영구 저장되기 때문이다', 'wrapper의 수명은 sort 호출이 끝날 때까지입니다. 동기적인 sort_r가 그 안에서 사용하므로 유효하며 반환 후 보관하는 API가 아닙니다.')],
        [('문맥 사용 예', 'sort_r의 priv에 비교 방향이나 기준 필드를 담은 읽기 전용 객체를 전달할 수 있습니다. 모든 비교에서 기준을 일관되게 유지해야 합니다.'),
         ('맞춤 교환 책임', '맞춤 교환 함수는 실제 원소 내용과 필요한 보조 정보를 올바르게 바꿔야 합니다. 정렬 본체는 콜백이 계약을 지켰는지 별도로 검증하지 않습니다.')])
